solution.solution.cpp:
int* findFirstNegative(int* a, int* b, int* c)
{
    if (a != nullptr && *a < 0) return a;
    if (b != nullptr && *b < 0) return b;
    if (c != nullptr && *c < 0) return c;
    return nullptr;
}

unitTests:
TEST("finds the first negative") { int x{ 4 }, y{ -2 }, z{ -9 }; CHECK(findFirstNegative(&x, &y, &z) == &y); }
TEST("the caller can fix it through the pointer") {
    int x{ 4 }, y{ 7 }, z{ -9 };
    int* found{ findFirstNegative(&x, &y, &z) };
    CHECK(found != nullptr);
    if (found) *found = 0;
    CHECK_EQ(z, 0);
}
TEST("none negative") { int x{ 0 }, y{ 1 }, z{ 2 }; CHECK(findFirstNegative(&x, &y, &z) == nullptr); }
TEST("null pointers are skipped") { int z{ -1 }; CHECK(findFirstNegative(nullptr, nullptr, &z) == &z); CHECK(findFirstNegative(nullptr, nullptr, nullptr) == nullptr); }

